<template><div class="works-pager"><button :disabled="!windowPages?.first.page.previousCursor||busy" @click="loadMore('previous')">加载前段</button><span>当前第 {{ firstIndex }}—{{ lastIndex }} 页 · 共 {{ page.total }} 项</span><button :disabled="!windowPages?.last.page.nextCursor||busy" @click="loadMore('next')">继续加载</button><button :disabled="busy" @click="refresh">刷新目录</button><button v-if="native" @click="openRight">右侧对照</button><a href="/works/trash" target="_blank" @click="openTrash">回收站</a><input aria-label="筛选已加载项" placeholder="筛选已加载项" :value="filter" @input="setFilter($event.target.value)" /><small>{{ message || '滚动自动续拉；筛选仅作用于已加载范围。' }}</small></div></template>
<script>
import { state,mutations,getters } from '@/store';import { router } from '@/router';import { nextTick } from 'vue';
import { openItem,directoryPage } from './directory.js';import { bridge } from './api.js';import { PageWindow } from './pageWindow.js';
export default {
 props:{page:Object},data(){return{windowPages:new PageWindow(state.req),busy:false,native:!!window.cefQuery,reportTimer:null,merging:false,message:'',filter:'',lastScroll:0,restored:false,refreshAnchor:null,refreshSelection:[]}},
 computed:{firstIndex(){return this.windowPages.first.page.index},lastIndex(){return this.windowPages.last.page.index}},
 watch:{page(){if(!this.merging){this.windowPages=new PageWindow(state.req);this.message='';this.filter=state.req.worksFilter||'';this.lastScroll=0;nextTick(()=>{if(this.refreshAnchor){this.restoreAnchor(this.refreshAnchor);this.selectPaths(this.refreshSelection);this.refreshAnchor=null;}this.report()})}}},
 async mounted(){window.worksFilesHost={refresh:change=>{if(!change?.canonicalPath)return this.refresh()},openMain:()=>openItem(state.req.source,state.req.path)};window.addEventListener('scroll',this.scrolled,true);window.addEventListener('click',this.queueReport,true);const restore=await this.report();if(typeof restore?.filter==='string')this.setFilter(restore.filter);await nextTick();if(restore?.anchor)this.restoreAnchor(restore.anchor);else if(restore?.scroll){const root=document.getElementById('main');if(root)root.scrollTop=restore.scroll}if(restore?.selected){this.selectPaths(restore.selected)}this.restored=true;this.lastScroll=document.getElementById('main')?.scrollTop||0;await this.report()},
 beforeUnmount(){clearTimeout(this.reportTimer);window.removeEventListener('scroll',this.scrolled,true);window.removeEventListener('click',this.queueReport,true);delete window.worksFilesHost},
 methods:{
 async openTrash(event){if(this.native){event.preventDefault();try{await bridge({action:'trash'})}catch(e){this.message=e.message}}},
 setFilter(value){this.filter=value;state.req.worksFilter=value},
 root(){return document.getElementById('main')},
 selectedPaths(){return state.selected.map(index=>state.req.items[index]?.path).filter(Boolean)},
 selectPaths(paths){mutations.resetSelected();for(const path of paths){const index=state.req.items.findIndex(item=>item.path===path);if(index>=0)mutations.addSelected(index)}},
 anchor(){const root=this.root();if(!root)return null;const top=root.getBoundingClientRect().top;const pagerBottom=this.$el.getBoundingClientRect().bottom;const elements=[...root.querySelectorAll('.listing-item[data-index]')];const element=elements.find(node=>node.getBoundingClientRect().bottom>Math.max(top,pagerBottom));if(!element)return null;const item=state.req.items[Number(element.dataset.index)];if(!item)return null;return {path:item.path,cursor:this.windowPages.cursorFor(item.path),offset:element.getBoundingClientRect().top-top}},
 restoreAnchor(anchor){const index=state.req.items.findIndex(item=>item.path===anchor.path);const root=this.root();const node=root?.querySelector(`.listing-item[data-index="${index}"]`);if(root&&node)root.scrollTop+=node.getBoundingClientRect().top-root.getBoundingClientRect().top-anchor.offset},
 queueReport(){clearTimeout(this.reportTimer);this.reportTimer=setTimeout(()=>this.report(),250)},
 scrolled(event){const root=this.root();if(event.target!==root)return;const current=root.scrollTop;const direction=current-this.lastScroll;this.lastScroll=current;this.queueReport();if(!this.restored||this.busy||this.message)return;if(direction>0&&root.scrollHeight-current-root.clientHeight<root.clientHeight)this.loadMore('next');else if(direction<0&&current<root.clientHeight/2)this.loadMore('previous')},
 report(){const anchor=this.anchor();const url=new URL(location.href);if(anchor?.cursor)url.searchParams.set('fcursor',anchor.cursor);return bridge({action:'navigation',canonicalPath:state.req.canonicalPath,url:url.pathname+url.search,scroll:this.root()?.scrollTop||0,anchor,filter:this.filter,selected:this.selectedPaths(),sorting:getters.sorting()})},
 async loadMore(direction){const pages=this.windowPages;const cursor=direction==='next'?pages.last.page.nextCursor:pages.first.page.previousCursor;if(!cursor||this.busy)return;this.busy=true;this.message='';const source=state.req.source,path=state.req.path;try{const data=await directoryPage(source,path,cursor);if(this.windowPages!==pages||state.req.source!==source||state.req.path!==path)return;const anchor=this.anchor(),selected=this.selectedPaths();pages.add(data,direction);this.merging=true;mutations.replaceRequest({...data,items:pages.items,page:pages.last.page,worksFilter:this.filter});this.selectPaths(selected);await nextTick();if(anchor)this.restoreAnchor(anchor);await nextTick();this.lastScroll=this.root()?.scrollTop||0;await this.report()}catch(e){this.message=e.status===410?'目录快照已失效，请刷新。':e.message}finally{this.merging=false;this.busy=false}},
 async refresh(){this.refreshAnchor=this.anchor();this.refreshSelection=this.selectedPaths();const q={...this.$route.query};delete q.fcursor;delete q.fpage;if(this.refreshAnchor)q.fanchor=this.refreshAnchor.path.split('/').filter(Boolean).pop();else delete q.fanchor;q.frefresh=String(Date.now());await router.replace({path:this.$route.path,query:q})},
 async openRight(){const item=state.req.items?.[state.selected?.[0]];try{await openItem(item?.source||state.req.source,item?.path||state.req.path,true)}catch(e){window.alert(e.message)}}
 }}
</script>
<style scoped>.works-pager{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:10px 16px;background:var(--surfacePrimary);border-bottom:1px solid var(--divider);position:sticky;top:0;z-index:4;font-size:12px;flex-shrink:0}.works-pager button{padding:5px 9px;border-radius:5px;border:1px solid var(--divider);background:var(--surfaceSecondary);color:var(--textPrimary);cursor:pointer}.works-pager small{opacity:.7}</style>
